(()=>{let customers=[],offset=0,selected=null,loading=false,version=0;const dialog=$('#reset-customer-dialog'),form=$('#reset-customer-form');
async function loadCustomers(){const current=++version;$('#customers-feedback').textContent='جارٍ تحميل العملاء…';try{const data=await api('/api/admin/customers?q='+encodeURIComponent($('#customer-search').value.trim())+'&offset='+offset);if(current!==version)return;customers=data.customers;$('#customers-list').innerHTML=customers.length?customers.map(c=>`<article class="portal-row customer-row"><div><strong>${E(c.full_name)}</strong><bdi dir="ltr">${E(c.phone)}</bdi><small>${Number(c.has_password)?'لديه كلمة مرور':'حساب قديم يحتاج تعيين كلمة مرور'}</small></div><button class="button outline" type="button" data-reset-customer="${E(c.id)}">تعيين كلمة مرور</button></article>`).join(''):'<p class="admin-empty">لا يوجد عملاء مطابقون.</p>';$('#customers-prev').disabled=offset===0;$('#customers-next').disabled=!data.has_more;$('#customers-feedback').textContent=customers.length?'عرض '+(offset+1)+' إلى '+(offset+customers.length):''}catch(e){if(current===version){$('#customers-feedback').textContent=e.message;$('#customers-list').replaceChildren()}}}
async function loadVisitors(){const box=$('#visitor-totals');box.textContent='جارٍ تحميل الإحصائية…';try{const data=await api('/api/admin/visitors'),t=data.totals;box.innerHTML=[['زوار اليوم',t.today_visitors],['زوار آخر 30 يومًا',t.month_visitors],['الزوار منذ التفعيل',t.unique_visitors],['مشاهدات الصفحات',t.page_views]].map(([label,value])=>`<article><small>${E(label)}</small><strong>${E(value)}</strong></article>`).join('');const known=new Map(data.daily.map(d=>[d.day,d])),days=[];for(let n=6;n>=0;n--){const date=new Date();date.setUTCDate(date.getUTCDate()-n);const day=date.toISOString().slice(0,10);days.push(known.get(day)||{day,visitors:0,page_views:0})}const max=Math.max(1,...days.map(d=>Number(d.visitors)));$('#visitor-days').innerHTML=days.map(d=>`<div class="visitor-day"><bdi dir="ltr">${E(d.day)}</bdi><div class="visitor-bar"><span style="width:${Math.max(0,Math.min(100,Number(d.visitors)/max*100))}%"></span></div><span>${E(d.visitors)} زائر · ${E(d.page_views)} مشاهدة</span></div>`).join('')}catch(e){box.textContent=e.message;$('#visitor-days').replaceChildren()}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab?.dataset.tab==='customers')loadCustomers();if(tab?.dataset.tab==='visitors')loadVisitors();const button=e.target.closest('[data-reset-customer]');if(button){selected=customers.find(c=>String(c.id)===button.dataset.resetCustomer);if(!selected)return;form.reset();form.querySelectorAll('input').forEach(input=>input.setCustomValidity(''));form.querySelectorAll('.password-policy-note').forEach(note=>note.remove());$('#reset-customer-feedback').textContent='';$('#reset-customer-name').textContent=selected.full_name+' — '+selected.phone;dialog.showModal();form.elements.password.focus()}});
$('#customer-refresh').onclick=()=>{offset=0;loadCustomers()};$('#customer-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();offset=0;loadCustomers()}};$('#customers-prev').onclick=()=>{offset=Math.max(0,offset-50);loadCustomers()};$('#customers-next').onclick=()=>{offset+=50;loadCustomers()};$('#visitors-refresh').onclick=loadVisitors;
$('#close-customer-reset').onclick=()=>{if(!loading)dialog.close()};dialog.addEventListener('cancel',e=>{if(loading)e.preventDefault()});dialog.addEventListener('close',()=>{form.reset();selected=null});
form.onsubmit=async e=>{e.preventDefault();if(loading||!selected)return;const feedback=$('#reset-customer-feedback');feedback.textContent='';if(form.elements.password.value!==form.elements.password_confirmation.value){feedback.textContent='كلمتا المرور غير متطابقتين.';form.elements.password_confirmation.focus();return}loading=true;const button=form.querySelector('[type=submit]');button.disabled=true;try{await api('/api/admin/customers/'+selected.id+'/password',Object.fromEntries(new FormData(form)));dialog.close();showSuccess('تم تعيين كلمة مرور العميل وإلغاء جلساته السابقة.');await loadCustomers()}catch(error){feedback.textContent=error.message}finally{loading=false;button.disabled=false}};
})();
